const W = 128;
const H = 128;

const PALETTE: Record<number, string | null> = {
    0: null,
    1: '#fbfaf9',
    2: '#ded9d6',
    3: '#bdb8b6',
    4: '#9a9695',
    5: '#706e6d',
    6: '#3d3c3c',
    7: '#191919',
    8: '#030303',
};

interface PixelPetHeadProps {
    scale?: number;
    className?: string;
}

export default function CatronautHappy({ scale = 3, className }: PixelPetHeadProps) {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const rafRef = useRef<number>(0);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        ctx.imageSmoothingEnabled = false;

        const PAD = 6;

        const drawGrid = (g: number[][]) => {
            for (let y = 0; y < H; y++) {
                for (let x = 0; x < W; x++) {
                    const color = PALETTE[g[y][x]];
                    if (!color) continue;
                    ctx.fillStyle = color;
                    ctx.fillRect(x, y + PAD, 1, 1);
                }
            }
        };

        let t = 0;
        let blinkTimer = 0;
        const BLINK_EVERY = 200;
        const BLINK_LEN = 8;

        const frame = () => {
            t += 1;
            blinkTimer += 1;
            if (blinkTimer > BLINK_EVERY) blinkTimer = 0;
            const blinking = blinkTimer < BLINK_LEN;

            const bob = Math.round(Math.sin(t * 0.045) * 1.6);

            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.save();
            ctx.translate(0, bob);
            drawGrid(blinking ? CLOSED_GRID : OPEN_GRID);
            ctx.restore();

            rafRef.current = requestAnimationFrame(frame);
        };

        frame();
        return () => cancelAnimationFrame(rafRef.current);
    }, []);

    return (
        <canvas
            ref={canvasRef}
            width={W}
            height={H + 12}
            className={className}
            style={{
                width: W * scale,
                height: (H + 12) * scale,
                maxWidth: 'none',
                maxHeight: 'none',
                display: 'block',
                flexShrink: 0,
                boxSizing: 'content-box',
                imageRendering: 'pixelated',
            }}
        />
    );
}
